import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';

/* ============================================================ config */
const P = 60, RH = 8, ZH = 22;            // block pitch, road half width, block-zone half
const BMIN = -4, BMAX = 3;                // block index range (8x8 blocks)
const FOG_COLOR = 0x070a12, FOG_D = 0.0040;
const VMAX = 42;
const LIMIT = 300;
const clamp01 = x => Math.min(1, Math.max(0, x));
const fmt = n => Math.round(n).toLocaleString('en-US');

/* deterministic rng */
let _s = 1337 >>> 0;
const rnd = () => { _s = (_s + 0x6D2B79F5) >>> 0; let t = Math.imul(_s ^ (_s >>> 15), 1 | _s);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };

/* ============================================================ dom */
const $ = id => document.getElementById(id);
const ui = { spd: $('spd'), score: $('scoreV'), best: $('bestV'), popup: $('popup'),
  nitro: $('nitroFill'), drift: $('driftFill'), chain: $('chainLbl'), fps: $('fps'),
  boot: $('boot'), paused: $('paused'), hint: $('hint') };
if (matchMedia('(pointer: coarse)').matches) document.body.classList.add('coarse');

/* ============================================================ renderer */
let renderer;
try {
  renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
} catch (e) { $('fallback').style.display = 'flex'; throw e; }
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
const PRMAX = Math.min(window.devicePixelRatio || 1, 1.75);
let PR = PRMAX;
renderer.setPixelRatio(PR);
renderer.setSize(innerWidth, innerHeight);
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(FOG_COLOR, FOG_D);
const camera = new THREE.PerspectiveCamera(62, innerWidth / innerHeight, 0.1, 900);

/* ============================================================ shared uniforms */
const U = {
  uTime:       { value: 0 },
  uFogColor:   { value: new THREE.Color(FOG_COLOR) },
  uFogDensity: { value: FOG_D },
  uMoonDir:    { value: new THREE.Vector3(0.42, 0.55, 0.32).normalize() },
  uCarPos:     { value: new THREE.Vector3() },
  uCarFwd:     { value: new THREE.Vector2(0, 1) },
  uHead:       { value: 1 },
  uBrake:      { value: 0 },
  uSpill:      { value: Array.from({ length: 12 }, () => new THREE.Vector4(0, 0, 1, 0)) },
  uSpillC:     { value: Array.from({ length: 12 }, () => new THREE.Vector3(0, 0, 0)) },
  uBlocks:     { value: null },
};

const GLSL_COMMON = `
uniform float uTime; uniform vec3 uFogColor; uniform float uFogDensity;
float hash21(vec2 p){ p = fract(p*vec2(233.34,851.73)); p += dot(p, p+23.45); return fract(p.x*p.y); }
float vnoise(vec2 p){ vec2 i=floor(p), f=fract(p); vec2 u=f*f*(3.0-2.0*f);
  return mix(mix(hash21(i),hash21(i+vec2(1.,0.)),u.x), mix(hash21(i+vec2(0.,1.)),hash21(i+vec2(1.,1.)),u.x), u.y); }
vec3 applyFog(vec3 c, float d){ float f = 1.0 - exp(-uFogDensity*uFogDensity*d*d);
  return mix(c, uFogColor, clamp(f, 0.0, 1.0)); }
`;

/* ============================================================ generated textures */
function radialTex(stops) {
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const g = c.getContext('2d');
  const gr = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  for (const [o, col] of stops) gr.addColorStop(o, col);
  g.fillStyle = gr; g.fillRect(0, 0, 128, 128);
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
}
const texGlow = radialTex([[0, 'rgba(255,255,255,1)'], [0.25, 'rgba(255,255,255,.55)'], [1, 'rgba(255,255,255,0)']]);
const texShadow = radialTex([[0, 'rgba(0,0,0,.62)'], [0.6, 'rgba(0,0,0,.35)'], [1, 'rgba(0,0,0,0)']]);

/* ============================================================ sky */
const skyMat = new THREE.ShaderMaterial({
  side: THREE.BackSide, depthWrite: false, fog: false,
  uniforms: { uTime: U.uTime, uMoonDir: U.uMoonDir },
  vertexShader: `varying vec3 vD;
    void main(){ vD = position; vec4 wp = modelMatrix*vec4(position,1.0);
      gl_Position = projectionMatrix * viewMatrix * wp; }`,
  fragmentShader: `varying vec3 vD; uniform float uTime; uniform vec3 uMoonDir;
    float h21(vec2 p){ p=fract(p*vec2(233.34,851.73)); p+=dot(p,p+23.45); return fract(p.x*p.y); }
    void main(){
      vec3 d = normalize(vD);
      float y = d.y;
      vec3 col = mix(vec3(0.085,0.11,0.19), vec3(0.010,0.014,0.032), smoothstep(-0.06,0.45,y));
      col += vec3(0.30,0.19,0.13) * pow(max(1.0-abs(y)*2.4,0.0),3.0) * 0.6;
      vec3 sd = d*420.0; vec3 id = floor(sd);
      vec2 off = vec2(h21(id.zx), h21(id.yz)) - 0.5;
      float hs = h21(id.xy + id.z*17.31);
      float sd2 = length(fract(sd).xy - 0.5 - off*0.6);
      float star = (1.0 - smoothstep(0.0,0.12,sd2)) * step(0.9935,hs);
      float tw = 0.55 + 0.45*sin(uTime*(0.6+3.0*h21(id.xz)) + hs*80.0);
      col += vec3(0.8,0.9,1.0) * star * tw * 1.35 * smoothstep(0.02,0.2,y);
      float md = dot(d, uMoonDir);
      col += vec3(0.92,0.96,1.05) * smoothstep(0.99950,0.99972,md) * 3.2;
      col += vec3(0.45,0.55,0.85) * (pow(max(md,0.0),350.0)*0.5 + pow(max(md,0.0),24.0)*0.10);
      gl_FragColor = vec4(col, 1.0);
    }`,
});
const sky = new THREE.Mesh(new THREE.SphereGeometry(640, 32, 16), skyMat);
sky.renderOrder = -1;
scene.add(sky);

/* ============================================================ lights */
scene.add(new THREE.HemisphereLight(0x24304a, 0x05070a, 0.55));
const moonLight = new THREE.DirectionalLight(0x7688b8, 0.5);
moonLight.position.copy(U.uMoonDir.value).multiplyScalar(100);
scene.add(moonLight);

/* ============================================================ ground */
const blockTexData = new Uint8Array(64);
const blockTex = new THREE.DataTexture(blockTexData, 8, 8, THREE.RedFormat, THREE.UnsignedByteType);
blockTex.magFilter = blockTex.minFilter = THREE.NearestFilter;
blockTex.needsUpdate = true;
U.uBlocks.value = blockTex;

const groundMat = new THREE.ShaderMaterial({
  uniforms: { uTime: U.uTime, uFogColor: U.uFogColor, uFogDensity: U.uFogDensity, uMoonDir: U.uMoonDir,
    uCarPos: U.uCarPos, uCarFwd: U.uCarFwd, uHead: U.uHead, uBrake: U.uBrake,
    uSpill: U.uSpill, uSpillC: U.uSpillC, uBlocks: U.uBlocks },
  vertexShader: `varying vec3 vW;
    void main(){ vec4 wp = modelMatrix*vec4(position,1.0); vW = wp.xyz;
      gl_Position = projectionMatrix * viewMatrix * wp; }`,
  fragmentShader: GLSL_COMMON + `
  uniform vec3 uMoonDir; uniform vec3 uCarPos; uniform vec2 uCarFwd;
  uniform float uHead; uniform float uBrake;
  uniform vec4 uSpill[12]; uniform vec3 uSpillC[12]; uniform sampler2D uBlocks;
  varying vec3 vW;
  const float P = 60.0; const float RH = 8.0; const float ZH = 22.0;
  float vband(float x, float a, float b){ return smoothstep(a-0.18,a,x) * (1.0 - smoothstep(b,b+0.18,x)); }
  float vsmooth(float w, float x){ return 1.0 - smoothstep(w*0.45, w, x); }
  void main(){
    vec2 xz = vW.xz;
    vec2 n = floor(xz/P + 0.5);
    vec2 lp = xz - n*P;
    vec2 a = abs(lp);
    float roadV = step(a.x, RH), roadH = step(a.y, RH);
    float onRoad = max(roadV, roadH);
    float inter = roadV * roadH;
    vec2 bid = floor(xz/P);
    float inCity = step(max(abs(bid.x), abs(bid.y)), 3.5);
    vec2 blp = xz - (bid + 0.5)*P;
    vec2 a2 = abs(blp);
    float mIn = ZH - max(a2.x, a2.y);
    float park = texture2D(uBlocks, (bid + 4.5)/8.0).r;
    float grain = vnoise(xz*0.6)*0.6 + vnoise(xz*2.9)*0.4;
    vec3 asphalt = vec3(0.052,0.058,0.070) * (0.75 + 0.5*grain);
    vec3 concrete = vec3(0.095,0.100,0.112) * (0.75 + 0.5*grain);
    vec3 grass = vec3(0.030,0.062,0.036) * (0.65 + 0.7*vnoise(xz*0.45 + 3.0));
    float pud = smoothstep(0.60, 0.74, vnoise(xz*0.15 + 7.3));
    asphalt *= mix(1.0, 0.5, pud);
    float tile = max(step(0.94, fract(a2.x*0.5)), step(0.94, fract(a2.y*0.5)));
    concrete *= 1.0 - 0.18*tile;
    vec3 col; float specAmt = 0.0;
    if (onRoad > 0.5) {
      col = asphalt; specAmt = 1.0;
      float cl  = vsmooth(0.22, abs(lp.x)) * step(2.0, a.y) * step(fract(xz.y/9.0), 0.55) * (1.0 - inter);
      float cl2 = vsmooth(0.22, abs(lp.y)) * step(2.0, a.x) * step(fract(xz.x/9.0), 0.55) * (1.0 - inter);
      float e1 = vband(abs(lp.x), RH-0.65, RH-0.25) * step(RH, a.y);
      float e2 = vband(abs(lp.y), RH-0.65, RH-0.25) * step(RH, a.x);
      float cw1 = vband(a.y, RH+0.8, RH+4.6) * step(a.x, RH) * step(fract(xz.y/1.7), 0.55);
      float cw2 = vband(a.x, RH+0.8, RH+4.6) * step(a.y, RH) * step(fract(xz.x/1.7), 0.55);
      float paint = clamp(cl + cl2 + e1 + e2 + cw1 + cw2, 0.0, 1.0) * inCity;
      paint *= 0.55 + 0.45*vnoise(xz*1.7);
      col = mix(col, vec3(0.55,0.56,0.58), paint*0.5);
      specAmt += paint*0.6;
    } else if (mIn < 2.7) { col = concrete*0.9; specAmt = 0.35; }
    else if (park > 0.5)  { col = grass; specAmt = 0.15; }
    else                  { col = mix(concrete, asphalt, 0.55); specAmt = 0.5; }
    col *= mix(0.55, 1.0, inCity);
    /* street-lamp pools (nearest intersection corner lamp) */
    float lampG = step(max(abs(n.x), abs(n.y)), 4.5);
    vec2 lampP = n*P + vec2(lp.x >= 0.0 ? 8.5 : -8.5, lp.y >= 0.0 ? 8.5 : -8.5);
    float pool = (1.0 - smoothstep(0.6, 7.5, length(xz - lampP))) * lampG;
    col += vec3(1.0,0.70,0.40) * pool * (0.5 + 0.12*vnoise(xz*2.0 + uTime*0.5));
    /* player headlights / brake / underglow pools */
    vec2 rel = xz - uCarPos.xz;
    float along = dot(rel, uCarFwd);
    float lat = dot(rel, vec2(-uCarFwd.y, uCarFwd.x));
    float fwdMask = step(0.0, along);
    float cone = fwdMask * (1.0 - smoothstep(4.0, 40.0, along));
    float spread = 1.0 - smoothstep(0.5, 1.2 + along*0.42, abs(lat));
    float head = cone * spread * uHead;
    float hot = fwdMask * (1.0 - smoothstep(2.0, 9.0, along)) * (1.0 - smoothstep(0.5, 2.0, abs(lat)));
    col += vec3(1.0,0.88,0.66) * (head*0.55 + hot*1.1);
    float beh = step(0.0, -along) * (1.0 - smoothstep(0.6, 5.5, -along)) * (1.0 - smoothstep(0.5, 2.4, abs(lat)));
    col += vec3(1.0,0.10,0.06) * beh * uBrake * 1.1;
    col += vec3(0.0,0.75,0.95) * (1.0 - smoothstep(0.6, 3.4, length(rel))) * 0.55;
    /* wet-road specular */
    vec3 V = normalize(cameraPosition - vW);
    float t = uTime*0.6;
    vec2 rp = xz*1.25;
    float n1 = vnoise(rp + vec2(t,-t*0.7)) - 0.5;
    float n2 = vnoise(rp.yx*1.13 + vec2(t*0.8,t)) - 0.5;
    vec3 N = normalize(vec3(n1*(0.18+0.5*pud), 1.0, n2*(0.18+0.5*pud)));
    float spec = pow(max(dot(N, normalize(V + uMoonDir)), 0.0), 120.0) * specAmt * (0.35 + 1.3*pud);
    col += vec3(0.50,0.60,0.85) * spec;
    vec3 Lh = normalize(vec3(uCarFwd.x, 0.16, uCarFwd.y));
    float sh = pow(max(dot(N, normalize(V + Lh)), 0.0), 70.0);
    col += vec3(1.0,0.85,0.6) * sh * head * 2.2;
    /* neon spill from nearby billboards */
    for (int i = 0; i < 12; i++) {
      vec4 s = uSpill[i];
      float g = (1.0 - smoothstep(0.0, s.z, length(xz - s.xy))) * s.w;
      if (g > 0.001) col += uSpillC[i] * g * (1.0 + sh*1.6);
    }
    col = applyFog(col, length(cameraPosition - vW));
    gl_FragColor = vec4(col, 1.0);
  }`,
});
const ground = new THREE.Mesh(new THREE.PlaneGeometry(1300, 1300), groundMat);
ground.rotation.x = -Math.PI / 2;
ground.frustumCulled = false;
scene.add(ground);

/* ============================================================ city generation */
const FACADES = ['#3a4149','#463f3a','#39424e','#4a4442','#35404a','#443c4a','#3f4a44','#4b4139'];
const buildList = [], bbCand = [], treeList = [], antList = [], parkSet = new Set();

for (let bi = BMIN; bi <= BMAX; bi++) for (let bj = BMIN; bj <= BMAX; bj++) {
  const idx = (bi + 4) * 8 + (bj + 4);
  const cx = (bi + 0.5) * P, cz = (bj + 0.5) * P;
  const distC = Math.hypot(cx, cz) / (8 * P * 0.5);
  const boost = Math.max(0, 1 - distC * 1.25);
  const isPark = rnd() < 0.07 + 0.12 * Math.min(1, distC);
  if (isPark) {
    parkSet.add(idx); blockTexData[idx] = 255;
    const nT = 9 + (rnd() * 8 | 0);
    for (let k = 0; k < nT; k++)
      treeList.push({ x: cx + (rnd() * 2 - 1) * (ZH - 4.5), z: cz + (rnd() * 2 - 1) * (ZH - 4.5),
        s: 0.8 + rnd() * 0.9, r: rnd() });
    continue;
  }
  let placed = 0;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    if (placed > 0 && rnd() < 0.32) continue;
    let w = 9 + rnd() * 6.5, d = 9 + rnd() * 6.5;
    let h = (9 + rnd() * 15) * (1 + boost * boost * (2.2 + rnd() * 5.5));
    h = Math.min(h, 165);
    if (h > 80) { w *= 0.72; d *= 0.72; }
    const scx = cx + sx * 11, scz = cz + sz * 11;
    const jx = (rnd() * 2 - 1) * Math.max(0, 8 - w / 2 - 0.4);
    const jz = (rnd() * 2 - 1) * Math.max(0, 8 - d / 2 - 0.4);
    const b = { x: scx + jx, z: scz + jz, w, d, h, seed: rnd(), c: FACADES[rnd() * FACADES.length | 0] };
    buildList.push(b); placed++;
    if (h > 26 && rnd() < 0.55) bbCand.push(b);
    if (h > 45) antList.push({ x: b.x, z: b.z, y: h });
    if (h > 20 && rnd() < 0.6)
      buildList.push({ x: b.x + (rnd() * 2 - 1) * w * 0.18, z: b.z + (rnd() * 2 - 1) * d * 0.18,
        w: 1.4 + rnd() * 1.8, d: 1.2 + rnd() * 1.4, h: 0.9 + rnd() * 1.1, seed: rnd(),
        c: '#2c3138' });
  }
  if (!placed) {
    const b = { x: cx, z: cz, w: 12, d: 12, h: 10 + rnd() * 22, seed: rnd(),
      c: FACADES[rnd() * FACADES.length | 0] };
    buildList.push(b);
  }
}
blockTex.needsUpdate = true;

/* ============================================================ buildings (instanced, procedural windows) */
const buildMat = new THREE.ShaderMaterial({
  uniforms: { uTime: U.uTime, uFogColor: U.uFogColor, uFogDensity: U.uFogDensity, uMoonDir: U.uMoonDir },
  vertexShader: `
    attribute float aSeed; attribute float aH;
    varying vec3 vW; varying vec3 vNw; varying vec3 vL; varying vec3 vCol;
    varying float vSeed; varying float vH;
    void main(){
      vL = position; vSeed = aSeed; vH = aH;
      mat4 im = mat4(1.0);
      #ifdef USE_INSTANCING
        im = instanceMatrix;
      #endif
      vec4 wp = modelMatrix * im * vec4(position, 1.0);
      vW = wp.xyz;
      vNw = normalize(mat3(modelMatrix) * mat3(im) * normal);
      #ifdef USE_INSTANCING_COLOR
        vCol = instanceColor;
      #else
        vCol = vec3(0.35);
      #endif
      gl_Position = projectionMatrix * viewMatrix * wp;
    }`,
  fragmentShader: GLSL_COMMON + `
    uniform vec3 uMoonDir;
    varying vec3 vW; varying vec3 vNw; varying vec3 vL; varying vec3 vCol;
    varying float vSeed; varying float vH;
    void main(){
      vec3 n = normalize(vNw);
      vec3 an = abs(n);
      vec2 fuv = vec2(0.0);
      if (an.x > 0.5) fuv = vec2(vW.z, vW.y);
      else if (an.z > 0.5) fuv = vec2(vW.x, vW.y);
      float moon = max(dot(n, uMoonDir), 0.0);
      float skyAmb = 0.35 + 0.35 * clamp(n.y*0.5 + 0.5, 0.0, 1.0);
      vec3 base = vCol * (0.16 + 0.10*hash21(vec2(vSeed*17.0, 3.7)));
      base *= 0.7 + 0.3*smoothstep(0.0, 26.0, vW.y);
      vec3 col = base * (skyAmb + 1.5*moon);
      vec3 emis = vec3(0.0);
      float neonSel = step(0.76, hash21(vec2(vSeed, 5.5)));
      vec3 nc = hash21(vec2(vSeed, 8.8)) < 0.5 ? vec3(0.05,0.9,1.0) : vec3(1.0,0.12,0.7);
      float pulse = 0.75 + 0.25*sin(uTime*2.2 + vSeed*23.0);
      if (an.y < 0.5) {
        vec2 g = vec2(fuv.x/2.4, (vW.y + 0.35)/3.0);
        vec2 cell = floor(g); vec2 f = fract(g);
        float wm = step(0.20, f.x)*step(f.x, 0.80)*step(0.28, f.y)*step(f.y, 0.82);
        wm *= step(4.3, vW.y) * (1.0 - step(vH - 0.7, vW.y));
        float r1 = hash21(cell + vSeed*37.1);
        float lit = step(0.50, r1);
        float b = 0.35 + 1.6*hash21(cell*1.91 + vSeed);
        vec3 wc = mix(vec3(1.0,0.72,0.42), vec3(0.62,0.78,1.0), step(0.55, hash21(cell + 91.3 + vSeed)));
        float tw = 0.8 + 0.2*sin(uTime*(0.4 + 2.6*hash21(cell + 7.7)) + r1*39.0);
        emis += wc * (wm * lit * b * tw * 1.5);
        if (vH > 9.0 && vW.y < 4.4) {
          float f2 = fract(fuv.x/4.5);
          float seg = step(0.12, f2)*step(f2, 0.88);
          float band = smoothstep(0.7, 1.1, vW.y) * (1.0 - smoothstep(3.4, 3.9, vW.y));
          float hr = hash21(vec2(vSeed, 9.2));
          vec3 sc = hr < 0.33 ? vec3(0.0,0.85,1.0) : (hr < 0.66 ? vec3(1.0,0.2,0.6) : vec3(1.0,0.6,0.15));
          emis += sc * seg * band * 1.4;
        }
        float eH = max(step(0.43, abs(vL.x)), step(0.43, abs(vL.z)));
        float em = max(eH, step(0.43, abs(vL.y)));
        emis += nc * em * neonSel * 2.0 * pulse;
      } else {
        float rim = step(0.42, max(abs(vL.x), abs(vL.z)));
        emis += nc * rim * neonSel * 1.6 * pulse;
      }
      col += emis;
      col = applyFog(col, length(cameraPosition - vW));
      gl_FragColor = vec4(col, 1.0);
    }`,
});
const boxGeo = new THREE.BoxGeometry(1, 1, 1); boxGeo.translate(0, 0.5, 0);
{
  const seeds = new Float32Array(buildList.length), hs = new Float32Array(buildList.length);
  buildList.forEach((b, i) => { seeds[i] = b.seed; hs[i] = b.h; });
  boxGeo.setAttribute('aSeed', new THREE.InstancedBufferAttribute(seeds, 1));
  boxGeo.setAttribute('aH', new THREE.InstancedBufferAttribute(hs, 1));
}
const buildMesh = new THREE.InstancedMesh(boxGeo, buildMat, buildList.length);
{
  const dummy = new THREE.Object3D(), col = new THREE.Color();
  buildList.forEach((b, i) => {
    dummy.position.set(b.x, 0, b.z);
    dummy.rotation.set(0, 0, 0);
    dummy.scale.set(b.w, b.h, b.d);
    dummy.updateMatrix();
    buildMesh.setMatrixAt(i, dummy.matrix);
    buildMesh.setColorAt(i, col.set(b.c));
  });
  buildMesh.instanceMatrix.needsUpdate = true;
  if (buildMesh.instanceColor) buildMesh.instanceColor.needsUpdate = true;
}
buildMesh.frustumCulled = false;
scene.add(buildMesh);

/* ============================================================ neon billboards */
const bbList = bbCand.sort(() => rnd() - 0.5).slice(0, 26);
const bbMat = new THREE.ShaderMaterial({
  side: THREE.DoubleSide,
  uniforms: { uTime: U.uTime, uFogColor: U.uFogColor, uFogDensity: U.uFogDensity },
  vertexShader: `
    attribute float aSeed;
    varying vec2 vUv; varying float vS; varying vec3 vW;
    void main(){
      vUv = uv; vS = aSeed;
      mat4 im = mat4(1.0);
      #ifdef USE_INSTANCING
        im = instanceMatrix;
      #endif
      vec4 wp = modelMatrix * im * vec4(position, 1.0);
      vW = wp.xyz;
      gl_Position = projectionMatrix * viewMatrix * wp;
    }`,
  fragmentShader: GLSL_COMMON + `
    varying vec2 vUv; varying float vS; varying vec3 vW;
