  const i = smokeHead; smokeHead = (smokeHead + 1) % SMOKE_N;
  smokePos[i * 3] = x; smokePos[i * 3 + 1] = y; smokePos[i * 3 + 2] = z;
  smokeVel[i * 3] = vx + (Math.random() - 0.5) * 1.6;
  smokeVel[i * 3 + 1] = 0.8 + Math.random() * 1.4;
  smokeVel[i * 3 + 2] = vz + (Math.random() - 0.5) * 1.6;
  smokeAge[i] = 0; smokeLife[i] = 1.1 + Math.random() * 0.9;
  smokeS[i] = 0.45 + Math.random() * 0.55; smokeA[i] = 0.7 * amt;
}
function updateSmoke(dt) {
  for (let i = 0; i < SMOKE_N; i++) {
    if (smokeA[i] <= 0) continue;
    smokeAge[i] += dt;
    if (smokeAge[i] >= smokeLife[i]) { smokeA[i] = 0; continue; }
    smokePos[i * 3] += smokeVel[i * 3] * dt;
    smokePos[i * 3 + 1] += smokeVel[i * 3 + 1] * dt;
    smokePos[i * 3 + 2] += smokeVel[i * 3 + 2] * dt;
    smokeVel[i * 3] *= (1 - dt * 1.4); smokeVel[i * 3 + 2] *= (1 - dt * 1.4);
    const k = smokeAge[i] / smokeLife[i];
    smokeA[i] = Math.pow(1 - k, 1.6) * 0.7;
    smokeS[i] += dt * 1.1;
  }
  smokeGeo.attributes.position.needsUpdate = true;
  smokeGeo.attributes.aA.needsUpdate = true;
  smokeGeo.attributes.aS.needsUpdate = true;
}

