let AC = null, master = null, eng = null, muted = false;
function initAudio() {
  if (AC) return;
  try {
    AC = new (window.AudioContext || window.webkitAudioContext)();
    master = AC.createGain(); master.gain.value = 0.75; master.connect(AC.destination);
    const o1 = AC.createOscillator(); o1.type = 'sawtooth';
    const o2 = AC.createOscillator(); o2.type = 'square';
    const g = AC.createGain(); g.gain.value = 0;
    const f = AC.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 400; f.Q.value = 2;
    const og2 = AC.createGain(); og2.gain.value = 0.4;
    o1.connect(f); o2.connect(og2); og2.connect(f); f.connect(g); g.connect(master);
    o1.start(); o2.start();
    const len = 2 * AC.sampleRate, buf = AC.createBuffer(1, len, AC.sampleRate), d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    const mkNoise = (type, freq, q) => {
      const src = AC.createBufferSource(); src.buffer = buf; src.loop = true;
      const flt = AC.createBiquadFilter(); flt.type = type; flt.frequency.value = freq; flt.Q.value = q;
      const ng = AC.createGain(); ng.gain.value = 0;
      src.connect(flt); flt.connect(ng); ng.connect(master); src.start(); return ng;
    };
    eng = { o1, o2, g, f, skid: mkNoise('bandpass', 750, 0.8), wind: mkNoise('lowpass', 420, 0.4) };
  } catch (e) { AC = null; }
}
function audioTick(rpm, th, slipAmt, spdN) {
  if (!AC || muted || !eng) return;
  const t = AC.currentTime;
  eng.o1.frequency.setTargetAtTime(50 + rpm * 150, t, 0.05);
  eng.o2.frequency.setTargetAtTime(25 + rpm * 75, t, 0.05);
  eng.f.frequency.setTargetAtTime(250 + rpm * 2600 + th * 500, t, 0.08);
  eng.g.gain.setTargetAtTime(0.028 + rpm * 0.05 + th * 0.02, t, 0.1);
  eng.skid.gain.setTargetAtTime(Math.min(0.16, slipAmt * 0.16), t, 0.06);
  eng.wind.gain.setTargetAtTime(spdN * 0.05, t, 0.2);
}
function thud() {
  if (!AC || muted || !master) return;
  const t = AC.currentTime;
  const o = AC.createOscillator(); o.type = 'triangle';
  o.frequency.setValueAtTime(120, t); o.frequency.exponentialRampToValueAtTime(38, t + 0.18);
  const g = AC.createGain(); g.gain.setValueAtTime(0.5, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.25);
  o.connect(g); g.connect(master); o.start(t); o.stop(t + 0.3);
}

/* ============================================================ input */
const keys = { up: 0, down: 0, left: 0, right: 0, hb: 0, nitro: 0 };
let camMode = 0, paused = false, hudVisible = true;
const KEYMAP = { KeyW: 'up', ArrowUp: 'up', KeyS: 'down', ArrowDown: 'down',
  KeyA: 'left', ArrowLeft: 'left', KeyD: 'right', ArrowRight: 'right',
  Space: 'hb', ShiftLeft: 'nitro', ShiftRight: 'nitro' };
addEventListener('keydown', e => {
  initAudio(); if (AC && AC.state === 'suspended') AC.resume();
  const k = KEYMAP[e.code];
  if (k) { keys[k] = 1; e.preventDefault(); }
  if (e.code === 'KeyC') camMode = (camMode + 1) % 3;
  if (e.code === 'KeyR') resetCar();
  if (e.code === 'KeyM') { muted = !muted; if (master) master.gain.value = muted ? 0 : 0.75; }
  if (e.code === 'KeyP') { paused = !paused; ui.paused.style.display = paused ? 'block' : 'none'; }
  if (e.code === 'KeyH') { hudVisible = !hudVisible; document.querySelectorAll('.ui,#touch').forEach(el => el.style.display = hudVisible ? '' : 'none'); }
  if (e.code === 'KeyF') ui.fps.style.display = ui.fps.style.display === 'block' ? 'none' : 'block';
});
addEventListener('keyup', e => { const k = KEYMAP[e.code]; if (k) keys[k] = 0; });
document.addEventListener('contextmenu', e => e.preventDefault());
document.querySelectorAll('.tbtn').forEach(b => {
  const k = b.dataset.k;
  const on = e => { e.preventDefault(); initAudio(); if (AC && AC.state === 'suspended') AC.resume(); keys[k] = 1; b.classList.add('on'); };
  const off = e => { e.preventDefault(); keys[k] = 0; b.classList.remove('on'); };
  b.addEventListener('pointerdown', on);
  b.addEventListener('pointerup', off);
  b.addEventListener('pointerleave', off);
  b.addEventListener('pointercancel', off);
});
/* pointer orbit */
let dragging = false, lastPX = 0, lastPY = 0, yawOff = 0, pitchOff = 0.3, orbitYaw = 0.6, zoom = 1, idleT = 0;
const cv = renderer.domElement;
cv.addEventListener('pointerdown', e => {
  initAudio(); if (AC && AC.state === 'suspended') AC.resume();
  dragging = true; lastPX = e.clientX; lastPY = e.clientY; idleT = 0;
});
addEventListener('pointermove', e => {
  if (!dragging) return;
  const dx = e.clientX - lastPX, dy = e.clientY - lastPY;
  lastPX = e.clientX; lastPY = e.clientY; idleT = 0;
  if (camMode === 1) orbitYaw -= dx * 0.006;
  else yawOff -= dx * 0.006;
  pitchOff = Math.min(1.25, Math.max(0.05, pitchOff + dy * 0.004));
});
addEventListener('pointerup', () => dragging = false);
addEventListener('pointercancel', () => dragging = false);
addEventListener('wheel', e => { zoom = Math.min(2.4, Math.max(0.55, zoom * Math.exp(e.deltaY * 0.0012))); }, { passive: true });

/* ============================================================ physics */
const state = { x: -2.6, z: -30, h: 0, vx: 0, vz: 0 };
let rollSm = 0, pitchSm = 0, accelSm = 0, nitro = 0.4, camShake = 0;
let slip = 0, spd = 0, drifting = false, driftEndT = 1;
function resetCar() {
  state.x = -2.6; state.z = -30; state.h = 0; state.vx = 0; state.vz = 0;
  skidLast[0] = skidLast[1] = null; pending = 0;
}
function blockIsSolid(bi, bj) {
  if (bi < BMIN || bi > BMAX || bj < BMIN || bj > BMAX) return false;
  return !parkSet.has((bi + 4) * 8 + (bj + 4));
}
function crash() {
  camShake = 0.7; thud();
  if (pending > 0) popup('WRECKED', true);
  pending = 0; chain = 0;
}
function physics(dt) {
  const f = { x: Math.sin(state.h), z: Math.cos(state.h) };
  const r = { x: -f.z, z: f.x };
  let vf = state.vx * f.x + state.vz * f.z;
  let vl = state.vx * r.x + state.vz * r.z;
  const th = keys.up, br = keys.down, hb = keys.hb;
  const st = (keys.right ? 1 : 0) - (keys.left ? 1 : 0);
  const boosting = keys.nitro && nitro > 0.01 && th ? 1 : 0;
  if (boosting) nitro = Math.max(0, nitro - dt * 0.3);
  else nitro = Math.min(1, nitro + dt * 0.012);
  let acc = 0;
  if (th) acc += (boosting ? 34 : 24) * (1 - Math.min(1, Math.abs(vf) / VMAX)) * (vf < 0 ? 2 : 1);
  if (br) acc += vf > 0.3 ? -40 : (vf > -12 ? -9 : 0);
  acc -= 0.004 * vf * Math.abs(vf) + 0.12 * vf;
  vf += acc * dt;
  const grip = hb ? 0.55 : 4.2;
  vl *= Math.exp(-grip * dt);
  if (hb) vf *= Math.exp(-0.12 * dt);
  const maxSteer = 0.62 / (1 + spd * 0.075);
  const steer = maxSteer * st;
  let w = (vf / 2.6) * Math.tan(steer) * (hb ? 1.35 : 1);
  const maxYaw = (hb ? 1.6 : 0.72) * Math.min(2.6, 13 / Math.max(spd, 4.5));
  w = THREE.MathUtils.clamp(w, -maxYaw, maxYaw);
  if (hb && th && Math.abs(st) > 0 && spd > 4) {
    const kick = st * Math.min(9, spd * 0.55);
    if (Math.abs(vl) < Math.abs(kick)) vl += (kick - vl) * Math.min(1, dt * 10);
  }
  slip = Math.atan2(vl, Math.max(2, Math.abs(vf)));
  w += (hb ? 0.9 : 2.6) * slip * clamp01(spd / 6);
  state.h -= w * dt;
  /* recompose with (possibly rotated) frame */
  const f2 = { x: Math.sin(state.h), z: Math.cos(state.h) };
  const r2 = { x: -f2.z, z: f2.x };
  state.vx = f2.x * vf + r2.x * vl;
  state.vz = f2.z * vf + r2.z * vl;
  state.x += state.vx * dt;
  state.z += state.vz * dt;
  accelSm += ((state.vx * f2.x + state.vz * f2.z) - accelSm) * Math.min(1, dt * 6);
  /* building-block collision */
  const bi = Math.floor(state.x / P), bj = Math.floor(state.z / P);
  if (blockIsSolid(bi, bj)) {
    const lx = state.x - (bi + 0.5) * P, lz = state.z - (bj + 0.5) * P;
    const lim = ZH - 3 - 0.9;
    if (Math.abs(lx) < lim && Math.abs(lz) < lim) {
      const px = lim - Math.abs(lx), pz = lim - Math.abs(lz);
      if (px < pz) {
        const s = Math.sign(lx) || 1;
        state.x = (bi + 0.5) * P + s * lim;
        if (Math.sign(state.vx) === s) { state.vx *= -0.3; state.vz *= 0.7; crash(); }
      } else {
        const s = Math.sign(lz) || 1;
        state.z = (bj + 0.5) * P + s * lim;
        if (Math.sign(state.vz) === s) { state.vz *= -0.3; state.vx *= 0.7; crash(); }
      }
    }
  }
  /* traffic collision */
  for (const c of traffic) {
    const dx = state.x - c.x, dz = state.z - c.z, d = Math.hypot(dx, dz);
    if (d < 2.5 && d > 0.001) {
      const nx = dx / d, nz = dz / d;
      state.x = c.x + nx * 2.5; state.z = c.z + nz * 2.5;
      const dot = state.vx * nx + state.vz * nz;
      if (dot < 0) {
        state.vx -= 1.6 * dot * nx; state.vz -= 1.6 * dot * nz;
        state.vx *= 0.55; state.vz *= 0.55; crash();
      }
    }
  }
  /* world bounds */
  state.x = THREE.MathUtils.clamp(state.x, -LIMIT, LIMIT);
  state.z = THREE.MathUtils.clamp(state.z, -LIMIT, LIMIT);
}

/* ============================================================ scoring */
let score = 0, best = 0, pending = 0, chain = 0, chainT = 0;
try { best = +(localStorage.getItem('dc_best') || 0) || 0; } catch (e) {}
ui.best.textContent = fmt(best);
let popTimer = null;
function popup(txt, bad) {
  ui.popup.textContent = txt;
  ui.popup.classList.toggle('bad', !!bad);
  ui.popup.classList.add('on');
  clearTimeout(popTimer);
  popTimer = setTimeout(() => ui.popup.classList.remove('on'), 950);
}
function bank() {
  const mult = 1 + Math.min(4, chain * 0.5);
  const pts = Math.round(pending) * mult;
  if (pts > 60) {
    score += pts; chain++; chainT = 2.6;
    nitro = Math.min(1, nitro + 0.2);
    popup('+' + fmt(pts) + (mult > 1 ? '  ×' + mult.toFixed(1) : ''));
    if (score > best) { best = score; try { localStorage.setItem('dc_best', best); } catch (e) {} ui.best.textContent = fmt(best); }
  }
  pending = 0;
}

/* ============================================================ traffic update */
function trafficTick(dt) {
  const dummy = new THREE.Object3D();
  for (let i = 0; i < TRAFFIC_N; i++) {
    const c = traffic[i];
    /* decide at intersections */
    const k = Math.round(c.pos / P);
    if (Math.abs(c.pos - k * P) < 0.6 && c.atK !== k) {
      c.atK = k;
      const mustTurn = Math.abs(k + c.dir) > 4;
      if (rnd() < 0.34 || mustTurn) {
        const newAxis = 1 - c.axis;
        const startLine = c.line;
        c.axis = newAxis; c.line = k; c.pos = startLine * P;
        if (Math.abs(startLine) >= 4) c.dir = startLine >= 4 ? -1 : 1;
        else c.dir = rnd() < 0.5 ? 1 : -1;
      }
    }
    /* brake for player */
    const target = c.spd;
    let brakeFor = false;
    {
      const dx = state.x - c.x, dz = state.z - c.z;
      const fh = { x: Math.sin(c.h), z: Math.cos(c.h) };
      const distF = dx * fh.x + dz * fh.z;
      const lat = Math.abs(dx * -fh.z + dz * fh.x);
      if (distF > 0 && distF < 13 && lat < 3.2) brakeFor = true;
    }
    const want = brakeFor ? 0 : target;
    c.spd += (want - c.spd) * Math.min(1, dt * 2.2);
    c.pos += c.dir * c.spd * dt;
    if (c.pos > 250 || c.pos < -250) { c.dir *= -1; }
    const off = c.axis === 0 ? 2.6 * c.dir : -2.6 * c.dir;
    if (c.axis === 0) { c.x = c.pos; c.z = c.line * P + off; c.h = c.dir > 0 ? Math.PI / 2 : -Math.PI / 2; }
    else { c.z = c.pos; c.x = c.line * P + off; c.h = c.dir > 0 ? 0 : Math.PI; }
    dummy.position.set(c.x, 0, c.z);
    dummy.rotation.set(0, c.h, 0);
    dummy.scale.set(1, 1, 1);
    dummy.updateMatrix();
    tBody.setMatrixAt(i, dummy.matrix);
    tCab.setMatrixAt(i, dummy.matrix);
    const fh = { x: Math.sin(c.h), z: Math.cos(c.h) };
    const rh = { x: -fh.z, z: fh.x };
    lightPosA.set([c.x + fh.x * 1.95 - rh.x * 0.55, 0.7, c.z + fh.z * 1.95 - rh.z * 0.55,
                   c.x + fh.x * 1.95 + rh.x * 0.55, 0.7, c.z + fh.z * 1.95 + rh.z * 0.55], i * 6);
    lightPosB.set([c.x - fh.x * 1.95 - rh.x * 0.5, 0.75, c.z - fh.z * 1.95 - rh.z * 0.5,
                   c.x - fh.x * 1.95 + rh.x * 0.5, 0.75, c.z - fh.z * 1.95 + rh.z * 0.5], i * 6);
  }
  tBody.instanceMatrix.needsUpdate = true;
  tCab.instanceMatrix.needsUpdate = true;
  headPts.geometry.attributes.position.needsUpdate = true;
  tailPts.geometry.attributes.position.needsUpdate = true;
}

/* ============================================================ camera */
const camPos = new THREE.Vector3(0, 6, -44), camLook = new THREE.Vector3(0, 1, 0);
let fovSm = 62;
function cameraTick(dt, t) {
  const f = { x: Math.sin(state.h), z: Math.cos(state.h) };
  const r = { x: -f.z, z: f.x };
  let want = new THREE.Vector3(), look = new THREE.Vector3();
  idleT += dt;
  if (camMode === 0) {
    yawOff *= Math.exp(-dt * (spd > 4 ? 1.5 : 0.35));
    const back = (8.4 + spd * 0.075) * zoom;
    const ang = state.h + Math.PI + yawOff;
    want.set(state.x + Math.sin(ang) * back, 2.5 + pitchOff * 4.2, state.z + Math.cos(ang) * back);
    look.set(state.x + f.x * 4.5 + state.vx * 0.22, 1.45,
             state.z + f.z * 4.5 + state.vz * 0.22);
    look.x += r.x * (state.vx * r.x + state.vz * r.z) * 0.06;
    look.z += r.z * (state.vx * r.x + state.vz * r.z) * 0.06;
  } else if (camMode === 1) {
    if (idleT > 3 && !dragging) orbitYaw += dt * 0.14;
    const rad = 11 * zoom;
    want.set(state.x + Math.sin(orbitYaw) * rad, Math.max(1.2, 1.2 + pitchOff * 11), state.z + Math.cos(orbitYaw) * rad);
    look.set(state.x, 1.2, state.z);
  } else {
    want.set(state.x + f.x * 1.05 + r.x * 0.34, 1.32, state.z + f.z * 1.05 + r.z * 0.34);
    look.set(state.x + f.x * 40, 1.0, state.z + f.z * 40);
  }
  const kp = 1 - Math.exp(-(camMode === 2 ? 30 : 6.5) * dt);
  const kl = 1 - Math.exp(-9 * dt);
  camPos.lerp(want, kp);
  camLook.lerp(look, kl);
  camera.position.copy(camPos);
  if (camShake > 0.003) {
    camShake *= Math.exp(-dt * 4);
    camera.position.x += (Math.random() - 0.5) * camShake * 0.5;
    camera.position.y += (Math.random() - 0.5) * camShake * 0.35;
  }
  camera.lookAt(camLook);
  const boosting = keys.nitro && nitro > 0.01 && keys.up;
  const fovT = Math.min(84, 62 + spd * 0.3 + (boosting ? 8 : 0));
  fovSm += (fovT - fovSm) * Math.min(1, dt * 4);
  if (Math.abs(camera.fov - fovSm) > 0.02) { camera.fov = fovSm; camera.updateProjectionMatrix(); }
}

/* ============================================================ hud */
let hudAcc = 0;
function hudTick(dt) {
  hudAcc += dt;
  if (hudAcc < 0.1) return;
  hudAcc = 0;
  ui.spd.textContent = Math.round(spd * 3.6);
  ui.score.textContent = fmt(score);
  ui.nitro.style.width = (nitro * 100).toFixed(0) + '%';
  ui.drift.style.width = (clamp01(Math.abs(slip) / 0.85) * 100).toFixed(0) + '%';
  ui.chain.textContent = drifting && chain > 0 ? 'CHAIN ×' + (1 + Math.min(4, chain * 0.5)).toFixed(1) : '';
}

/* ============================================================ main loop */
const clock = new THREE.Clock();
let T = 0, emaDt = 16.6, qTimer = 0, fpsAcc = 0, fpsN = 0;
function applyQuality() {
  renderer.setPixelRatio(PR); composer.setPixelRatio(PR);
  renderer.setSize(innerWidth, innerHeight); composer.setSize(innerWidth, innerHeight);
}
function tick() {
  const dt = Math.min(clock.getDelta(), 0.05);
  T += dt;
  emaDt = emaDt * 0.94 + dt * 1000 * 0.06;
  qTimer += dt;
  if (qTimer > 2.5) {
    qTimer = 0;
    if (emaDt > 19 && PR > 0.85) { PR = Math.max(0.8, PR - 0.25); applyQuality(); }
    else if (emaDt < 13 && PR < PRMAX) { PR = Math.min(PRMAX, PR + 0.25); applyQuality(); }
  }
  fpsAcc += dt; fpsN++;
  if (fpsAcc > 0.5) { ui.fps.textContent = Math.round(fpsN / fpsAcc) + ' FPS · ' + PR.toFixed(2) + 'x'; fpsAcc = 0; fpsN = 0; }

  if (!paused) {
    const sub = 2, sdt = dt / sub;
    for (let i = 0; i < sub; i++) physics(sdt);
    spd = Math.hypot(state.vx, state.vz);
    drifting = Math.abs(slip) > 0.16 && spd > 5;
    trafficTick(dt);
    updateSmoke(dt);

    /* drift fx + scoring */
    const f = { x: Math.sin(state.h), z: Math.cos(state.h) };
    const r = { x: -f.z, z: f.x };
    const slipAmt = clamp01((Math.abs(slip) - 0.15) * 2.4) * clamp01(spd / 16);
    if (drifting) {
      pending += spd * Math.abs(slip) * dt * 14;
      chainT = 2.2; driftEndT = 0;
      ui.hint.classList.add('hide');
      for (let wi = 0; wi < 2; wi++) {
        const s2 = wi === 0 ? -0.85 : 0.85;
        const wx = state.x - f.x * 1.42 + r.x * s2;
        const wz = state.z - f.z * 1.42 + r.z * s2;
        skidDraw(wi, wx, wz);
        if (Math.random() < slipAmt * 0.9)
          spawnSmoke(wx, 0.25, wz, state.vx * 0.25, state.vz * 0.25, slipAmt);
      }
    } else {
      skidLast[0] = skidLast[1] = null;
      driftEndT += dt;
      if (pending > 0 && (driftEndT > 0.55 || spd < 4)) bank();
    }
    if (skidDirty) { skidTex.needsUpdate = true; skidDirty = false; }
    chainT -= dt; if (chainT <= 0) chain = 0;

    /* car transform */
    car.position.set(state.x, 0, state.z);
    car.rotation.y = state.h;
    const vf = state.vx * f.x + state.vz * f.z;
    const vl = state.vx * r.x + state.vz * r.z;
    rollSm += (THREE.MathUtils.clamp(-vl * 0.05, -0.16, 0.16) - rollSm) * Math.min(1, dt * 8);
    pitchSm += (THREE.MathUtils.clamp(-accelSm * 0.0035, -0.05, 0.05) - pitchSm) * Math.min(1, dt * 6);
    bodyG.rotation.z = rollSm;
    bodyG.rotation.x = pitchSm;
    const maxSteer = 0.62 / (1 + spd * 0.075);
    const steer = maxSteer * ((keys.right ? 1 : 0) - (keys.left ? 1 : 0));
    for (const g of steerGroups) g.rotation.y = -steer * 1.1;
    for (const w of wheels) w.rotation.x -= (vf / 0.34) * dt;
    const braking = keys.down || keys.hb;
    tailMat.emissiveIntensity = braking ? 5 : 1.6;
    U.uBrake.value += ((braking ? 1 : 0) - U.uBrake.value) * Math.min(1, dt * 10);
    /* nitro flames */
    const boosting = keys.nitro && nitro > 0.01 && keys.up;
    for (const s of flames) {
      s.visible = boosting;
      if (boosting) s.scale.set(0.5 + Math.random() * 0.3, 0.9 + Math.random() * 0.8, 1);
    }
    beamMat.uniforms.uOp.value = 0.42 + 0.05 * Math.sin(T * 47) + 0.03 * Math.sin(T * 23);
    /* uniforms */
    U.uCarPos.value.set(state.x, 0, state.z);
    U.uCarFwd.value.set(f.x, f.z);
    /* neon spill: 12 nearest billboards */
    const arr = bbList.map(b => ({ b, d: (b.x - state.x) ** 2 + (b.z - state.z) ** 2 })).sort((a, b) => a.d - b.d);
    for (let i = 0; i < 12; i++) {
      const s = U.uSpill.value[i], c = U.uSpillC.value[i];
      if (i < arr.length && arr[i].d < 36000) {
        const b = arr[i].b;
        s.set(b.x, b.z, b.glowR, 0.75);
        c.set(b.glowColor[0], b.glowColor[1], b.glowColor[2], 1.0);
      } else s.w = 0;
    }
    audioTick(clamp01(Math.abs(vf) / VMAX + (keys.up ? 0.12 : 0)), keys.up, slipAmt, clamp01(spd / VMAX));
  }

  U.uTime.value = T;
  sky.position.copy(camera.position);
  for (const b of beaconMats) b.m.opacity = 0.08 + 0.92 * Math.pow(Math.max(0, Math.sin(T * 2.4 + b.ph)), 3);
  cameraTick(dt, T);
  hudTick(dt);
  composer.render();
}

/* ============================================================ resize + boot */
addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  composer.setSize(innerWidth, innerHeight);
});
camera.position.set(-2.6, 5, -44);
camera.lookAt(-2.6, 1, -25);
renderer.setAnimationLoop(tick);
setTimeout(() => ui.boot.classList.add('hide'), 1400);
setTimeout(() => ui.hint.classList.add('hide'), 12000);
